/**
 * Golden-snapshot parity test: the behavior-preservation safety net.
 *
 * `friendly_error_golden.json` is generated by the temporary Rust test
 * `friendly_error::tests::write_golden_parity_snapshot`, which records the
 * EXACT title/explanation/suggestion the old Rust `friendly_error` system
 * rendered for a representative input matrix (every errno arm, every typed
 * VolumeError variant, every git kind, the empty-root case, every
 * provider×category). This test asserts the FE factories reproduce those
 * strings byte-for-byte on macOS, proving the move is behavior-preserving.
 *
 * Its two siblings pin what Windows and Linux read for the same matrix
 * (`friendly_error_golden.windows.json`, `.linux.json`). They were generated once
 * from these factories, right after the errors gained their per-OS branches, and
 * checked by hand against `docs/notes/windows-port/copy-final.json`.
 *
 * All three are FROZEN. If this test and a golden disagree, the copy drifted:
 * fix the factory or the catalog, do NOT regenerate the golden. A deliberate
 * copy change hand-edits just the affected values (`DETAILS.md` § Test strategy).
 */

import { describe, expect, it } from 'vitest'
import macosGolden from './__fixtures__/friendly_error_golden.json'
import windowsGolden from './__fixtures__/friendly_error_golden.windows.json'
import linuxGolden from './__fixtures__/friendly_error_golden.linux.json'
import { feMessage } from './friendly-error-matrix'
import { withPlatform } from '#lib/platform/test-platform.js'
import type { Platform } from '#lib/platform/index.js'

interface GoldenEntry {
  category: string
  title: string
  explanation: string
  suggestion: string
  retryHint: boolean
  actionKind: string | null
}

const GOLDENS: [Platform, Record<string, GoldenEntry>][] = [
  ['macos', macosGolden],
  ['windows', windowsGolden],
  ['linux', linuxGolden],
]

for (const [platform, golden] of GOLDENS) {
  describe(`friendly-error parity on ${platform} (FE factories reproduce the frozen golden)`, () => {
    it('covers every golden key (no missing/extra mappings)', () => {
      const goldenKeys = Object.keys(golden).sort()
      expect(goldenKeys.length).toBeGreaterThan(80)
      expect(goldenKeys).toEqual(Object.keys(macosGolden).sort())
    })

    for (const key of Object.keys(golden).sort()) {
      it(`reproduces "${key}"`, ({ onTestFinished }) => {
        onTestFinished(withPlatform(platform))
        const expected = golden[key]
        const actual = feMessage(key)
        expect(actual.title, `${key} title`).toBe(expected.title)
        expect(actual.message, `${key} explanation`).toBe(expected.explanation)
        expect(actual.suggestion, `${key} suggestion`).toBe(expected.suggestion)
      })
    }
  })
}
